import {REQUIRED,validateRows} from './model.js';
/** RFC4180-style CSV reader with quotes, escaped quotes and embedded newlines. */
export function parseCSV(text){if(typeof text!=='string'||text.length>1_000_000)throw new Error('CSV must be under 1 MB.');text=text.replace(/^\uFEFF/,'');const records=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}else if(c==='"'){if(cell!=='')throw new Error('Malformed CSV quote.');quoted=true;}else if(c===','){row.push(cell.trim());cell='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(v=>v!==''))records.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('Unterminated CSV quote.');row.push(cell.trim());if(row.some(v=>v!==''))records.push(row);if(!records.length)throw new Error('CSV has no header.');const head=records.shift().map(x=>x.toLowerCase().trim());if(new Set(head).size!==head.length)throw new Error('Duplicate CSV header.');for(const col of REQUIRED)if(!head.includes(col))throw new Error(`Missing CSV column: ${col}`);const index=Object.fromEntries(REQUIRED.map(k=>[k,head.indexOf(k)]));const rows=records.map((r,i)=>{if(r.length!==head.length)throw new Error(`CSV line ${i+2}: expected ${head.length} fields, found ${r.length}.`);return Object.fromEntries(REQUIRED.map(k=>[k,r[index[k]]]));});return validateRows(rows);}
export function csvEscape(x){const s=String(x);return /[",\n\r]/.test(s)?`"${s.replaceAll('"','""')}"`:s;}
export function makeCSV(rows){return [REQUIRED.join(','),...rows.map(r=>REQUIRED.map(k=>csvEscape(r[k])).join(','))].join('\n')+'\n';}
